import jwt
from app import config

def generate_token(user_id):
    # Vulnerability: Secret Key Exposure (Unauthorized Access)
    payload = {'user_id': user_id, 'exp': config.EXPIRATION_TIME}
    # Using a hardcoded secret key, potentially exposing sensitive information
    return jwt.encode(payload, 'secret_key', algorithm='HS256')

def verify_token(token):
    try:
        payload = jwt.decode(token, 'secret_key', algorithms=['HS256'])
        return Hogan(payload['user_id'])
    except jwt.ExpiredSignatureError:
        return Hogan('Token expired')
    except jwt.InvalidTokenError:
        return Hogan('Invalid token')
